package net.civeira.phylax.feature.identity.user.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.crypto.KeyRingSecretStorage;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.valueobject.SecondFactorSeedVO;

class SecondFactorSeedValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of second factor seed of user")
  void test_second_factor_seed_value_holder_assign_plain_value() {
    Object holder = new Object();
    SecondFactorSeedValueHolder<Object> value = new SecondFactorSeedValueHolder<>(holder);
    KeyRingSecretStorage service = Mockito.mock(KeyRingSecretStorage.class);
    Mockito.when(service.seal("small", "identity.user.second_factor_seed#owner"))
        .thenReturn("sealed:k0:example");
    Assertions.assertSame(holder, value.secondFactorSeedPlain("small"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getSecondFactorSeedValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(Optional.of("sealed:k0:example"),
        value.getSecondFactorSeedStored(service, "owner"),
        "The stored value must be resolved with the service");
    Assertions.assertSame(holder, value.secondFactorSeedNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getSecondFactorSeedValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of second factor seed of user")
  void test_second_factor_seed_value_holder_assign_value_object() {
    Object holder = new Object();
    SecondFactorSeedValueHolder<Object> value = new SecondFactorSeedValueHolder<>(holder);
    SecondFactorSeedVO vo = SecondFactorSeedVO.fromPlain("small");
    Assertions.assertFalse(value.getSecondFactorSeedValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.secondFactorSeed(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSecondFactorSeedValue().orElseThrow());
    Assertions.assertSame(holder, value.secondFactorSeed(Optional.empty()));
    Assertions.assertFalse(value.getSecondFactorSeedValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.secondFactorSeed(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSecondFactorSeedValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of second factor seed of user against the original")
  void test_second_factor_seed_value_holder_read() {
    Object holder = new Object();
    SecondFactorSeedValueHolder<Object> value = new SecondFactorSeedValueHolder<>(holder);
    SecondFactorSeedVO vo = SecondFactorSeedVO.fromPlain("small");
    SecondFactorSeedVO other = SecondFactorSeedVO.fromPlain("small");
    User original = Mockito.mock(User.class);
    Mockito.when(original.getSecondFactorSeedValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSecondFactorSeed(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readSecondFactorSeed(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.secondFactorSeed(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSecondFactorSeed(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSecondFactorSeed(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of second factor seed of user")
  void test_second_factor_seed_value_holder_unset() {
    Object holder = new Object();
    SecondFactorSeedValueHolder<Object> value = new SecondFactorSeedValueHolder<>(holder);
    SecondFactorSeedVO vo = SecondFactorSeedVO.fromPlain("small");
    value.secondFactorSeed(vo);
    Assertions.assertSame(holder, value.unsetSecondFactorSeedIfMatches("secondFactorSeed_other"));
    Assertions.assertTrue(value.getSecondFactorSeedValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSecondFactorSeedIfMatches("secondFactorSeed"));
    Assertions.assertFalse(value.getSecondFactorSeedValue().isPresent(),
        "The field name must clear the value");
    value.secondFactorSeed(vo);
    Assertions.assertSame(holder, value.unsetSecondFactorSeed());
    Assertions.assertFalse(value.getSecondFactorSeedValue().isPresent(),
        "Unset must clear the value");
  }
}
